 File prepare()throws Exception{String version;try(InputStream in=getAssets().open("bundle.sha256")){version=readStream(in).trim();}String targetName="program-"+version.substring(0,16);File core=new File(getFilesDir(),targetName);File done=new File(core,".ready");if(done.isFile())return core;bundleUpdated=true;File[] dirs=getFilesDir().listFiles();if(dirs!=null)for(File d:dirs)if(d.isDirectory()&&d.getName().startsWith("program-")&&!d.getName().equals(targetName))deleteTree(d);core.mkdirs();String prefix=core.getCanonicalPath()+File.separator;int count=0;long total=0;try(ZipInputStream in=new ZipInputStream(getAssets().open("program.bundle"))){ZipEntry entry;byte[] b=new byte[65536];while((entry=in.getNextEntry())!=null){File out=new File(core,entry.getName());if(!out.getCanonicalPath().startsWith(prefix)||++count>40000)throw new IOException("无效内置资源路径");if(entry.isDirectory()){out.mkdirs();continue;}out.getParentFile().mkdirs();try(OutputStream stream=new FileOutputStream(out)){int n;while((n=in.read(b))>0){if((total+=n)>1500L*1024*1024)throw new IOException("内置资源异常");stream.write(b,0,n);}}}}try(OutputStream out=new FileOutputStream(done)){out.write(version.getBytes("UTF-8"));}return core;}
 static void deleteTree(File f){if(f==null||!f.exists())return;File[] kids=f.listFiles();if(kids!=null)for(File k:kids)deleteTree(k);f.delete();}
