  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri u=request.getUrl();if(local(u))return false;if(request.isForMainFrame()&&request.hasGesture()&&"https".equals(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}@Override public void onPageFinished(WebView view,String url){android.util.Log.i("ShinyPlayer","PAGE_READY "+url);}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())Toast.makeText(MainActivity.this,"页面加载失败，可返回后重试："+error.getDescription(),Toast.LENGTH_LONG).show();}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onConsoleMessage(ConsoleMessage m){android.util.Log.println(m.messageLevel()==ConsoleMessage.MessageLevel.ERROR?android.util.Log.ERROR:android.util.Log.INFO,"ShinyWeb",m.message()+" @"+m.lineNumber());return true;}@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> result,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=result;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");String[] types=params.getAcceptTypes();if(types!=null&&types.length>0&&Arrays.stream(types).allMatch(t->t.contains("/")))intent.putExtra(Intent.EXTRA_MIME_TYPES,types);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(intent,10);}catch(Exception e){fileCallback.onReceiveValue(null);fileCallback=null;}return true;}@Override public void onShowCustomView(View view,CustomViewCallback callback){if(customView!=null){callback.onCustomViewHidden();return;}customView=view;customCallback=callback;root.addView(view,new FrameLayout.LayoutParams(-1,-1));fitViewport();web.setVisibility(View.GONE);}@Override public void onHideCustomView(){hideVideo();}@Override public boolean onJsAlert(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}@Override public boolean onJsConfirm(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});
