 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&fileCallback!=null){List<Uri> found=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)found.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)found.add(data.getData());}fileCallback.onReceiveValue(found.isEmpty()?null:found.toArray(new Uri[0]));fileCallback=null;}if(request==11&&pendingExport!=null&&result==RESULT_OK&&data!=null&&data.getData()!=null){File f=new File(user,"exports/"+pendingExport);Uri target=data.getData();pendingExport=null;new Thread(()->{try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(target,"w")){byte[] b=new byte[65536];int n;while((n=in.read(b))>0)out.write(b,0,n);main.post(()->Toast.makeText(this,"已保存到所选位置",Toast.LENGTH_LONG).show());f.delete();}catch(Exception e){main.post(()->Toast.makeText(this,"保存失败："+e.getMessage(),Toast.LENGTH_LONG).show());}},"ShinyExport").start();}}
 boolean isHarmonyOS(){try{Class<?> cls=Class.forName("com.huawei.system.BuildEx");Object brand=cls.getMethod("getOsBrand").invoke(null);if(brand!=null&&"harmony".equalsIgnoreCase(String.valueOf(brand)))return true;}catch(Throwable ignored){}try{String m=(Build.DISPLAY+" "+Build.FINGERPRINT+" "+Build.PRODUCT).toLowerCase(Locale.ROOT);if(m.contains("harmony")||m.contains("ohos"))return true;}catch(Throwable ignored){}return false;}
